def num_decodings(s):
    if not s or s[0] == '0':
        return 0

    dp = [0] * (len(s) + 1)
    dp[0], dp[1] = 1, 1

    for i in range(2, len(s) + 1):
        # Check if the current digit is not zero
        if s[i-1] != '0':
            dp[i] += dp[i-1]

        # Check if the two-digit number formed is between 10 and 26
        two_digit = int(s[i-2:i])
        if 10 <= two_digit <= 26:
            dp[i] += dp[i-2]

    return dp[len(s)]
