    temp = matrix_power(matrix, n // 2)
    result = matrix_multiplication(temp, temp)

    if n % 2 != 0:
        result = matrix_multiplication(result, [[1, 1], [1, 0]])

    return result

def optimized_fibonacci(n: int) -> int:
    if n == 0:
        return 0
    elif n == 1:
        return 1

    F = [[1, 1], [1, 0]]
    result = matrix_power(F, n - 1)

    return result[0][0]
