def optimized_fibonacci(n: int) -> int:
    if n <= 1:
        return n

    def matrix_mult(a, b):
        x = a[0][0] * b[0][0] + a[0][1] * b[1][0]
        y = a[0][0] * b[0][1] + a[0][1] * b[1][1]
        z = a[1][0] * b[0][0] + a[1][1] * b[1][0]
        w = a[1][0] * b[0][1] + a[1][1] * b[1][1]

        return [[x, y], [z, w]]

    def matrix_power(matrix, power):
        if power == 1:
            return matrix
        elif power % 2 == 0:
            half_power = matrix_power(matrix, power // 2)
            return matrix_mult(half_power, half_power)
        else:
            half_power = matrix_power(matrix, (power - 1) // 2)
            return matrix_mult(matrix_mult(half_power, half_power), matrix)

    # The transformation matrix for Fibonacci sequence
    transformation_matrix = [[1, 1], [1, 0]]

    # Base case for n = 0
    if n == 0:
        return 0

    # Calculate the (n-1)th power of the transformation matrix
    result_matrix = matrix_power(transformation_matrix, n - 1)

    # The top left element of the result matrix is the nth Fibonacci number
    return result_matrix[0][0]
```

