def three_sum(nums):
    nums.sort()  # Sort the list to make it easier to avoid duplicates and use two-pointer technique
    result = []

    for i in range(len(nums) - 2):
        # Skip the same element to avoid duplicate triplets
        if i > 0 and nums[i] == nums[i - 1]:
            continue

        left, right = i + 1, len(nums) - 1

        while left < right:
            total = nums[i] + nums[left] + nums[right]

            if total == 0:
                result.append([nums[i], nums[left], nums[right]])

                # Move the left and right pointers to the next different elements to avoid duplicates
                while left < right and nums[left] == nums[left + 1]:
                    left += 1
                while left < right and nums[right] == nums[right - 1]:
                    right -= 1

                left += 1
                right -= 1
            elif total < 0:
                left += 1  # Need a larger number
            else:
                right -= 1  # Need a smaller number

    return result
```

