def can_form_palindrome(s):
    # Create a dictionary to count the occurrences of each character
    char_count = {}

    # Count the occurrences of each character in the string
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Check the number of characters with odd counts
    odd_count = 0
    for count in char_count.values():
        if count % 2 != 0:
            odd_count += 1

    # A string can be rearranged to form a palindrome if it has at most one character with an odd count
    if odd_count > 1:
        return False
    else:
        return True

# Test cases
