def pair_sum(nums: list[int], target: int) -> list[list[int]]:
    if not nums:
        return []

    nums.sort()  # Sort the list to make it easier to find pairs
    pairs = []
    left, right = 0, len(nums) - 1

    while left < right:
        current_sum = nums[left] + nums[right]

        if current_sum == target:
            # If the current pair is not already in the list, add it
            if not pairs or (pairs and pairs[-1] != [nums[left], nums[right]]):
                pairs.append([nums[left], nums[right]])
            left += 1
            right -= 1

        elif current_sum < target:
            left += 1

        else:
            right -= 1

    return pairs
```

