def kmp_search(text: str, pattern: str) -> list:
    def compute_lps_array(pattern: str) -> list:
        length = 0  # length of the previous longest prefix suffix
        lps = [0] * len(pattern)  # lps[0] is always 0
        i = 1

        while i < len(pattern):
            if pattern[i] == pattern[length]:
                length += 1
                lps[i] = length
                i += 1
            else:
                if length != 0:
                    length = lps[length - 1]
                else:
                    lps[i] = 0
                    i += 1
        return lps

    if not pattern:
        return [0]

    lps = compute_lps_array(pattern)
    i = 0  # index for text
    j = 0  # index for pattern
    indices = []

    while i < len(text):
        if pattern[j] == text[i]:
            i += 1
            j += 1

        if j == len(pattern):
            indices.append(i - j)
            j = lps[j - 1]

        elif i < len(text) and pattern[j] != text[i]:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1

    return indices
```

