from typing import List, Set

def find_possible_sums(numbers: List[int]) -> Set[int]:
    if not numbers:
        return set()

    possible_sums = {0}  # Start with the sum of 0

    for number in numbers:
        new_sums = set()
        for current_sum in possible_sums:
            new_sum = current_sum + number
            new_sums.add(new_sum)
            new_sums.add(current_sum)  # Adding the current sum without the new number

        possible_sums.update(new_sums)

    return possible_sums
