        if len(path) >= 2:
            result.add(tuple(path))

        for i in range(start, len(nums)):
            if not path or nums[i] >= path[-1]:
                backtrack(i + 1, path + [nums[i]])

    result = set()
    backtrack(0, [])
    return [list(subseq) for subseq in result]
