def shift_string(s, n):
    result = ""
    for char in s:
        if 'a' <= char <= 'z':
            # Calculate the new character with wrap-around using modulo operation
            new_char = chr((ord(char) - ord('a') + n) % 26 + ord('a'))
            result += new_char
        else:
            # Non-alphabetic characters are added without any changes
            result += char
    return result
```

