def combination_sum(nums, target):
    def backtrack(start, target, path):
        if target == 0:
            result.append(path)
            return
        if target < 0:
            return

        for i in range(start, len(nums)):
            if i > start and nums[i] == nums[i - 1]:
                continue  # Skip duplicates
            backtrack(i + 1, target - nums[i], path + [nums[i]])

    nums.sort()  # Sort the list to handle duplicates and to make the combinations in non-decreasing order
    result = []
    backtrack(0, target, [])
    return result
