from typing import List

def subarray_sum(nums: List[int], k: int) -> int:
    # Dictionary to store the frequency of cumulative sums
    cumulative_sum_freq = {0: 1}
    current_sum = 0
    count = 0

    for num in nums:
        # Update the current cumulative sum
        current_sum += num

        # Check if there is a subarray (ending at the current index) which sums to k
        if (current_sum - k) in cumulative_sum_freq:
            count += cumulative_sum_freq[current_sum - k]

        # Update the frequency of the current cumulative sum
        if current_sum in cumulative_sum_freq:
            cumulative_sum_freq[current_sum] += 1
        else:
            cumulative_sum_freq[current_sum] = 1

    return count
```

