    count_s1 = {}
    count_s2 = {}

    for char in filtered_s1:
        if char in count_s1:
            count_s1[char] += 1
        else:
            count_s1[char] = 1

    for char in filtered_s2:
        if char in count_s2:
            count_s2[char] += 1
        else:
            count_s2[char] = 1

    # Compare the frequency dictionaries
    if count_s1 == count_s2:
        return True
    else:
        return False
