    s2 = ''.join(filter(str.isalpha, s2)).lower()

    # If the lengths of the strings are different, they cannot be anagrams
    if len(s1) != len(s2):
        return False

    # Create a dictionary to count occurrences of each character in the first string
    char_count = {}

    for char in s1:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Decrement the count for each character found in the second string
    for char in s2:
        if char in char_count:
            char_count[char] -= 1
        else:
            # If the character is not found in the dictionary, they are not anagrams
            return False

    # Check if all counts are zero
    for count in char_count.values():
        if count != 0:
            return False

    return True
