def calculate_binary_gap(number: int) -> int:
    if not isinstance(number, int) or number < 0:
        raise TypeError("Input value must be a non-negative 'int' type")

    binary_representation = bin(number)[2:]  # Convert number to binary and remove the '0b' prefix
    longest_gap = 0
    current_gap = 0

    for bit in binary_representation:
        if bit == '0':
            current_gap += 1
        else:
            if current_gap > 0:
                longest_gap = max(longest_gap, current_gap)
            current_gap = 0

    return longest_gap
```

