from typing import Dict, List, Tuple
import heapq

def shortest_path_with_stops(graph: Dict[str, List[Tuple[str, int]]], start: str, end: str, max_stops: int) -> int:
    if start not in graph or end not in graph:
        return -1

    # Priority queue to store (current_weight, current_node, current_stops)
    pq = [(0, start, 0)]
    visited = {}

    while pq:
        current_weight, current_node, current_stops = heapq.heappop(pq)

        # If the current node is the destination and the number of stops is within the limit
        if current_node == end and current_stops <= max_stops:
            return current_weight

        # If the current node has already been visited with fewer stops, skip it
        if current_node in visited and visited[current_node] <= current_stops:
            continue

        visited[current_node] = current_stops

        # Explore all the neighbors
        for neighbor, weight in graph[current_node]:
            if current_stops + 1 <= max_stops:
                heapq.heappush(pq, (current_weight + weight, neighbor, current_stops + 1))

    # If no path is found within the given constraints
    return -1
```

