class CoinChange:
    def __init__(self, coins: list[int]):
        # Initialize with a list representing the denominations of the coins.
        self.coins = coins

    def min_coins(self, amount: int) -> int:
        # Create a list to store the minimum coins needed for each amount up to the given amount
        dp = [float('inf')] * (amount + 1)

        # Base case: 0 coins are needed to make amount 0
        dp[0] = 0

        # Iterate through each amount from 1 to the given amount
