from typing import List

def max_robbery_in_circle(nums: List[int]) -> int:
    if not nums:
        return 0
    if len(nums) == 1:
        return nums[0]

    def rob_linear(houses: List[int]) -> int:
        if not houses:
            return 0
        if len(houses) == 1:
            return houses[0]

        dp = [0] * len(houses)
        dp[0] = houses[0]
        dp[1] = max(houses[0], houses[1])

        for i in range(2, len(houses)):
            dp[i] = max(dp[i-1], dp[i-2] + houses[i])

        return dp[-1]

    # Case 1: Rob the first house, so we cannot rob the last house
    case1 = rob_linear(nums[:-1])

    # Case 2: Rob the last house, so we cannot rob the first house
    case2 = rob_linear(nums[1:])

    # The maximum amount of money we can rob is the maximum of the two cases
    return max(case1, case2)
```

