def find_pairs_with_sum(nums, k):
    nums.sort()  # Sort the list to make it easier to find pairs
    pairs = []
    left, right = 0, len(nums) - 1

    while left < right:
        current_sum = nums[left] + nums[right]

        if current_sum == k:
            if (nums[left], nums[right]) not in pairs:
                pairs.append((nums[left], nums[right]))
            left += 1
            right -= 1
        elif current_sum < k:
            left += 1
        else:
            right -= 1

    return pairs
```

