def rotate_matrix(matrix: list[list[int]]) -> list[list[int]]:
    N = len(matrix)

    # Transpose the matrix
    for i in range(N):
        for j in range(i, N):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]

    # Reverse each row
    for i in range(N):
        matrix[i].reverse()

    return matrix
