from typing import List, Tuple

def minimize_max_latency(n: int, links: List[Tuple[int, int, int]]) -> int:
    from collections import defaultdict
    import heapq

    def bfs(max_latency: int) -> bool:
        if not links:
            return True

        graph = defaultdict(list)
        for u, v, w in links:
            if w <= max_latency:
                graph[u].append(v)
                graph[v].append(u)

        visited = [False] * (n + 1)
        queue = [1]
        visited[1] = True

        while queue:
            current = queue.pop(0)

            for neighbor in graph[current]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)

        return all(visited)

    if not links or n == 1:
        return 0

    left, right = 1, 100  # Given constraints
    result = float('inf')

    while left <= right:
        mid = (left + right) // 2

        if bfs(mid):
            result = min(result, mid)
            right = mid - 1
        else:
            left = mid + 1

    return result if result != float('inf') else 0
