def minimize_max_latency(n: int, links: List[Tuple[int, int, int]]) -> int:
    def can_optimize(max_latency: int) -> bool:
        from collections import defaultdict
        from heapq import heappop, heappush

        graph = defaultdict(list)
        for u, v, w in links:
            if w <= max_latency:
                graph[u].append((v, w))
                graph[v].append((u, w))

        visited = [False] * (n + 1)
        heap = [(0, 1)]  # (current_latency, current_node)

        while heap:
            current_latency, current_node = heappop(heap)

            if visited[current_node]:
                continue

            visited[current_node] = True

            if current_node == n:
                return True

            for neighbor, weight in graph[current_node]:
                if not visited[neighbor] and current_latency + weight <= max_latency:
                    heappush(heap, (current_latency + weight, neighbor))

        return False

    if not links or n == 1:
        return 0

    left, right = 1, 100  # Given constraints
    result = 0

    while left <= right:
        mid = (left + right) // 2

        if can_optimize(mid):
            result = mid
            right = mid - 1
        else:
            left = mid + 1

    return result
