        graph = [[] for _ in range(n + 1)]
        for u, v, w in links:
            if w <= max_latency:
                graph[u].append(v)
                graph[v].append(u)

        # Use BFS to check if all servers are reachable from server 1
        visited = [False] * (n + 1)
        queue = deque([1])
        visited[1] = True

        while queue:
            current = queue.popleft()

            for neighbor in graph[current]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)

        # Check if all servers are visited
        for i in range(1, n + 1):
            if not visited[i]:
                return False

        return True

    if not links or n == 1:
        return 0

    # Binary search for the minimum possible maximum latency
    left, right = 1, 100  # Given the constraint 1 <= w <= 100
    best_max_latency = float('inf')

    while left <= right:
        mid = (left + right) // 2

        if can_reach_all_servers(mid):
            best_max_latency = mid
            right = mid - 1
        else:
            left = mid + 1

    return best_max_latency
