from typing import List

def find_combinations(nums: List[int], target: int) -> List[List[int]]:
    def backtrack(start, current_combination, current_sum):
        if current_sum == target:
            result.append(current_combination[:])
            return
        if current_sum > target:
            return

        for i in range(start, len(nums)):
            if i > start and nums[i] == nums[i - 1]:
                continue  # Skip duplicates

            current_combination.append(nums[i])
            backtrack(i + 1, current_combination, current_sum + nums[i])
            current_combination.pop()

    nums.sort()  # Sort the array to handle duplicates and to get combinations in non-decreasing order
    result = []
    backtrack(0, [], 0)
    return result
