def min_steps_to_target(target: int) -> int:
    if target == 0:
        return 0

    step = 0
    current_sum = 0

    while current_sum != target:
        step += 1
        current_sum += step

        if current_sum > target:
            if (current_sum - target) % 2 == 0:
                return step
            else:
                step += 1
                current_sum += step
                return step

    return step
```

