def aggregate_sensor_data(readings: List[Tuple[str, float]]) -> Dict[str, float]:
    if not readings:
        return {}

    # Dictionary to store the sum of readings and count of readings for each hour
    hourly_sum = {}
    hourly_count = {}

    for timestamp, value in readings:
        # Convert the timestamp string to a datetime object
        dt = datetime.strptime(timestamp, "%Y-%m-%d %H:%M:%S")

        # Create a key for the hour by setting the minute and second to 0
        hour_key = dt.strftime("%Y-%m-%d %H:00:00")

        # Add the reading value to the sum for this hour
        if hour_key in hourly_sum:
            hourly_sum[hour_key] += value
        else:
            hourly_sum[hour_key] = value

        # Increment the count of readings for this hour
        if hour_key in hourly_count:
            hourly_count[hour_key] += 1
        else:
            hourly_count[hour_key] = 1

    # Dictionary to store the average readings for each hour
    average_readings = {}

    # Calculate the average for each hour
    for hour_key in hourly_sum:
        average = hourly_sum[hour_key] / hourly_count[hour_key]
        average_readings[hour_key] = average

    return average_readings
