def count_pairs(nums, k):
    num_count = {}
    pair_count = 0

    for num in nums:
        complement = k - num
        if complement in num_count:
            pair_count += num_count[complement]

        if num in num_count:
            num_count[num] += 1
        else:
            num_count[num] = 1

    return pair_count
