def count_pairs(nums, k):
    nums.sort()  # Sort the list to make it easier to find pairs
    left, right = 0, len(nums) - 1
    count = 0

    while left < right:
        current_sum = nums[left] + nums[right]

        if current_sum == k:
            count += 1
            left += 1
            right -= 1

            # Skip duplicate elements to avoid counting the same pair multiple times
            while left < right and nums[left] == nums[left - 1]:
                left += 1
            while left < right and nums[right] == nums[right + 1]:
                right -= 1

        elif current_sum < k:
            left += 1
        else:
            right -= 1

    return count
