def bubble_sort(arr):
    n = len(arr)
    swap_count = 0

    for i in range(n):
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:
                # Swap the elements
                arr[j], arr[j+1] = arr[j+1], arr[j]
                swap_count += 1

    return arr, swap_count
