def char_info(s):
    """
    This function takes a string as input and returns a dictionary where the keys are the unique characters
    from the string, and the values are the ASCII values of those characters. If a character appears more than
    once in the string, its corresponding value in the dictionary is a list of all the positions (indexes) it
    appears in the string.

    :param s: Input string
    :return: Dictionary with characters as keys and either ASCII value or list of positions as values
    """
    result = {}

    for i, char in enumerate(s):
        if char in result:
            if isinstance(result[char], list):
                result[char].append(i)
            else:
                result[char] = [result[char], i]
        else:
            result[char] = ord(char)

    return result

# Test cases
print(char_info('hello'))  # Output: {'h': 104, 'e': 101, 'l': [2, 3], 'o': 111}
print(char_info('test'))   # Output: {'t': 116, 'e': 101, 's': 115, 't': [3]}
print(char_info('aabbcc')) # Output: {'a': 97, 'b': 98, 'c': 99}
```

