import math

def is_prime(n: int) -> bool:
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def is_mersenne_prime(num: int) -> bool:
    """Check if a number is a Mersenne prime."""
    if num + 1 <= 1:
        return False

    # Check if num + 1 is a power of two
    if (num + 1) & num != 0:
        return False

    # Calculate the exponent p
    p = int(math.log2(num + 1))

    # Check if p is a prime number
    return is_prime(p)
