from typing import List, Tuple

class WordCountEngine:
    def __init__(self, text: str):
        self.text = text.lower()
        self.word_count = {}

    def count_words(self):
        words = self.text.split()
        for word in words:
            if word in self.word_count:
                self.word_count[word] += 1
            else:
                self.word_count[word] = 1

    def get_top_k_words(self, k: int) -> List[Tuple[str, int]]:
        # Sort the words first by frequency (descending) and then lexicographically (ascending)
        sorted_words = sorted(self.word_count.items(), key=lambda x: (-x[1], x[0]))

        # Return the top k words
        return sorted_words[:k]
```

