import re
from collections import Counter

class WordCountEngine:
    def __init__(self, text: str):
        self.text = text.lower()
        self.word_counts = {}

    def count_words(self):
        # Use regex to find words and ignore punctuation
        words = re.findall(r'\b\w+\b', self.text)
        self.word_counts = Counter(words)

    def get_top_k_words(self, k: int) -> List[Tuple[str, int]]:
        if not self.word_counts:
            self.count_words()

        # Sort words by frequency (descending) and then lexicographically (ascending)
        sorted_words = sorted(self.word_counts.items(), key=lambda x: (-x[1], x[0]))

        # Return the top k words
        return sorted_words[:k]
```

