def min_subarray_len(nums, k):
    if not nums:
        return 0

    from collections import defaultdict

    prefix_sum = 0
    min_length = float('inf')
    sum_dict = defaultdict(lambda: float('inf'))
    sum_dict[0] = -1

    for i, num in enumerate(nums):
        prefix_sum += num

        if prefix_sum == k:
            min_length = min(min_length, i + 1)

        if (prefix_sum - k) in sum_dict:
            min_length = min(min_length, i - sum_dict[prefix_sum - k])

        if sum_dict[prefix_sum] == float('inf'):
            sum_dict[prefix_sum] = i

    return min_length if min_length != float('inf') else 0
```

