import re

def common_words(sentences):
    if not sentences:
        return []

    # Convert all sentences to lower case to ensure case-insensitivity
    sentences = [sentence.lower() for sentence in sentences]

    # Use a regular expression to find words in the sentences
    words = [re.findall(r'\b\w+\b', sentence) for sentence in sentences]

    # Create a dictionary to count occurrences of each word
    word_count = {}
    for word_list in words:
        for word in word_list:
            if word in word_count:
                word_count[word] += 1
            else:
                word_count[word] = 1

    # Find words that appear in every sentence
    common_words = [word for word, count in word_count.items() if count == len(sentences)]

    return common_words
```

