def common_words(sentences):
    from collections import defaultdict

    if not sentences:
        return []

    # Helper function to extract words from a sentence
    def extract_words(sentence):
        words = []
        word = ""
        for char in sentence:
            if char.isalnum():
                word += char
            else:
                if word:
                    words.append(word.lower())
                    word = ""
        if word:
            words.append(word.lower())
        return words

    # Dictionary to store the count of each word
    word_count = defaultdict(int)

    # Extract words from the first sentence and initialize the count
    for word in extract_words(sentences[0]):
        word_count[word] += 1

    # Iterate over the remaining sentences
    for sentence in sentences[1:]:
        current_words = extract_words(sentence)
        current_count = defaultdict(int)

        # Count the words in the current sentence
        for word in current_words:
            if word in word_count:
                current_count[word] += 1

        # Update the word_count dictionary to keep only the common words
        for word in list(word_count.keys()):
            if word not in current_count or current_count[word] != word_count[word]:
                del word_count[word]

    # Return the list of common words
    return list(word_count.keys())
