def evaluate_expression(expr):
    try:
        # Remove whitespace from the expression
        expr = expr.replace(" ", "")

        # Evaluate the expression using Python's eval function
        result = eval(expr)

        return result
    except ZeroDivisionError:
        return "Error: Division by zero"
    except SyntaxError:
        return "Error: Invalid syntax"
