def process_operations(lst: list, operations: list) -> list:
    if not isinstance(lst, list):
        raise TypeError("List must be provided as input.")

    for operation in operations:
        if not isinstance(operation, tuple) or len(operation) < 1:
            raise ValueError("Operation not correctly formatted or unsupported.")

        op_type = operation[0]
        if op_type not in ['append', 'insert', 'delete', 'reverse']:
            raise ValueError("Operation not correctly formatted or unsupported.")

        if op_type == 'append':
            if len(operation) != 2:
                raise ValueError("Operation not correctly formatted or unsupported.")
            lst.append(operation[1])

        elif op_type == 'insert':
            if len(operation) != 3:
                raise ValueError("Operation not correctly formatted or unsupported.")
            if not isinstance(operation[1], int) or operation[1] < 0 or operation[1] > len(lst):
                raise IndexError("Insert operation index out of range.")
            lst.insert(operation[1], operation[2])

        elif op_type == 'delete':
            if len(operation) != 2:
                raise ValueError("Operation not correctly formatted or unsupported.")
            if not isinstance(operation[1], int) or operation[1] < 0 or operation[1] >= len(lst):
                raise IndexError("Delete operation index out of range.")
            del lst[operation[1]]

        elif op_type == 'reverse':
            lst.reverse()

    return lst
