        result = []

        while i < len(seq1) and j < len(seq2):
            if seq1[i] == seq2[j]:
                result.append(seq1[i])
                i += 1
                j += 1
            elif seq1[i] < seq2[j]:
                i += 1
            else:
                j += 1

        return result

    common_seq = reduce(common_subsequence, lists)

    return common_seq
