def optimal_delivery_route(n: int, distances: List[List[int]]) -> int:
    from functools import lru_cache

    @lru_cache(None)
    def dp(mask, pos):
        if mask == (1 << n) - 1:
            return distances[pos][0]  # Return to the depot

        min_distance = float('inf')
        for city in range(n):
            if not (mask & (1 << city)):
                new_distance = distances[pos][city] + dp(mask | (1 << city), city)
                min_distance = min(min_distance, new_distance)

        return min_distance

    return dp(1, 0)  # Start from the depot (city 0) and include it in the mask
