def optimal_delivery_route(n: int, distances: List[List[int]]) -> int:
    from functools import lru_cache

    # Using bitmask DP to keep track of visited locations
    @lru_cache(None)
    def dp(mask, pos):
        # If all locations are visited (mask has all bits set except the start location)
        if mask == (1 << n) - 2:
            return distances[pos][0]  # Return to the depot from the current position

        min_distance = float('inf')

        # Try to visit each location
        for city in range(n):
            if (mask & (1 << city)) == 0:  # If the city is not visited
                # Visit the city and update the minimum distance
                min_distance = min(min_distance, distances[pos][city] + dp(mask | (1 << city), city))

        return min_distance

    # Start from the depot (location 0) and no locations are visited initially (mask = 0)
    return dp(0, 0)
