        self.root = None

    def insert(self, value: int) -> None:
        if not self.root:
            self.root = TreeNode(value)
        else:
            self._insert_recursive(self.root, value)

    def _insert_recursive(self, current_node: TreeNode, value: int) -> None:
        if value < current_node.value:
            if current_node.left is None:
                current_node.left = TreeNode(value)
            else:
                self._insert_recursive(current_node.left, value)
        else:
            if current_node.right is None:
                current_node.right = TreeNode(value)
            else:
                self._insert_recursive(current_node.right, value)

    def delete(self, value: int) -> None:
        self.root = self._delete_recursive(self.root, value)

    def _delete_recursive(self, current_node: TreeNode, value: int) -> Optional[TreeNode]:
        if not current_node:
            return current_node

        if value < current_node.value:
            current_node.left = self._delete_recursive(current_node.left, value)
        elif value > current_node.value:
            current_node.right = self._delete_recursive(current_node.right, value)
        else:
            if not current_node.left:
                return current_node.right
            elif not current_node.right:
                return current_node.left

            temp_value = self._get_min_value(current_node.right)
            current_node.value = temp_value
            current_node.right = self._delete_recursive(current_node.right, temp_value)

        return current_node

    def _get_min_value(self, current_node: TreeNode) -> int:
        while current_node.left is not None:
            current_node = current_node.left
        return current_node.value

    def search(self, value: int) -> bool:
        return self._search_recursive(self.root, value)

    def _search_recursive(self, current_node: TreeNode, value: int) -> bool:
        if not current_node:
            return False

        if value == current_node.value:
            return True
        elif value < current_node.value:
            return self._search_recursive(current_node.left, value)
        else:
            return self._search_recursive(current_node.right, value)

    def in_order_successor(self, value: int) -> Optional[int]:
        current_node = self.search_node(self.root, value)
        if not current_node or not current_node.right:
            return None

        current_node = current_node.right
        while current_node.left:
            current_node = current_node.left

        return current_node.value

