            return current_node

        if value < current_node.value:
            return self.search_node(current_node.left, value)
        else:
            return self.search_node(current_node.right, value)

    def lowest_common_ancestor(self, value1: int, value2: int) -> Optional[int]:
        lca_node = self._lowest_common_ancestor_recursive(self.root, value1, value2)
        if lca_node:
