        if current_node.value == value1 or current_node.value == value2:
            return current_node

        left_lca = self._lowest_common_ancestor_recursive(current_node.left, value1, value2)
        right_lca = self._lowest_common_ancestor_recursive(current_node.right, value1, value2)

        if left_lca and right_lca:
            return current_node

        return left_lca if left_lca else right_lca

