                current_node.right = TreeNode(value)
            else:
                self._insert_recursive(current_node.right, value)

    def delete(self, value: int) -> None:
        self.root = self._delete_recursive(self.root, value)

    def _delete_recursive(self, current_node: TreeNode, value: int) -> Optional[TreeNode]:
        if current_node is None:
            return current_node

        if value < current_node.value:
            current_node.left = self._delete_recursive(current_node.left, value)
        elif value > current_node.value:
            current_node.right = self._delete_recursive(current_node.right, value)
        else:
            if current_node.left is None:
                return current_node.right
            elif current_node.right is None:
                return current_node.left

            temp = self._get_min_value_node(current_node.right)
            current_node.value = temp.value
            current_node.right = self._delete_recursive(current_node.right, temp.value)

        return current_node

    def search(self, value: int) -> bool:
        return self._search_recursive(self.root, value) is not None

    def _search_recursive(self, current_node: TreeNode, value: int) -> Optional[TreeNode]:
        if current_node is None or current_node.value == value:
            return current_node

        if value < current_node.value:
            return self._search_recursive(current_node.left, value)
        else:
            return self._search_recursive(current_node.right, value)

    def in_order_successor(self, value: int) -> Optional[int]:
        current_node = self._search_recursive(self.root, value)
        if current_node is None:
            return None

        if current_node.right is not None:
            return self._get_min_value(current_node.right)

        successor = None
        ancestor = self.root
        while ancestor is not None:
            if current_node.value < ancestor.value:
                successor = ancestor
                ancestor = ancestor.left
            else:
                ancestor = ancestor.right

        return successor.value if successor else None

    def _get_min_value_node(self, node: TreeNode) -> TreeNode:
        current = node
        while current.left is not None:
            current = current.left
        return current

    def _get_min_value(self, node: TreeNode) -> int:
        current = node
        while current.left is not None:
            current = current.left
        return current.value

    def lowest_common_ancestor(self, value1: int, value2: int) -> Optional[int]:
        return self._lca_recursive(self.root, value1, value2)

    def _lca_recursive(self, current_node: TreeNode, value1: int, value2: int) -> Optional[TreeNode]:
        if current_node is None:
            return None

        if current_node.value > value1 and current_node.value > value2:
            return self._lca_recursive(current_node.left, value1, value2)

        if current_node.value < value1 and current_node.value < value2:
            return self._lca_recursive(current_node.right, value1, value2)

        return current_node.value

    def is_balanced(self) -> bool:
        return self._is_balanced_recursive(self.root) != -1

    def _is_balanced_recursive(self, current_node: TreeNode) -> int:
        if current_node is None:
            return 0

        left_height = self._is_balanced_recursive(current_node.left)
        if left_height == -1:
            return -1

        right_height = self._is_balanced_recursive(current_node.right)
        if right_height == -1:
            return -1

        if abs(left_height - right_height) > 1:
            return -1

        return max(left_height, right_height) + 1
