def optimize_shelf_stacks(n_shelves: int, max_height: int, n_items: int) -> int:
    if n_items == 0:
        return 0

    # If there are more items than the maximum height times the number of shelves, it's not possible to store all items
    if n_items > n_shelves * max_height:
        return -1

    # Start with one stack and increase the number of stacks if the current stack exceeds the maximum height
    current_stack_height = 0
    number_of_stacks = 1

    for i in range(n_items):
        if current_stack_height + 1 > max_height:
            # If adding another item exceeds the maximum height, start a new stack
            number_of_stacks += 1
            current_stack_height = 1
        else:
            # Otherwise, add the item to the current stack
            current_stack_height += 1

    return number_of_stacks
