def find_triplets(nums):
    nums.sort()  # Sort the array to make it easier to avoid duplicates and use two-pointer technique
    triplets = []

    for i in range(len(nums) - 2):
        # If the current value is the same as the one before, skip it to avoid duplicates
        if i > 0 and nums[i] == nums[i - 1]:
            continue

        left, right = i + 1, len(nums) - 1

        while left < right:
            current_sum = nums[i] + nums[left] + nums[right]

            if current_sum == 0:
                triplets.append([nums[i], nums[left], nums[right]])

                # Move the left and right pointers to the next different elements to avoid duplicates
                while left < right and nums[left] == nums[left + 1]:
                    left += 1
                while left < right and nums[right] == nums[right - 1]:
                    right -= 1

                left += 1
                right -= 1

            elif current_sum < 0:
                left += 1  # Need a larger number
            else:
                right -= 1  # Need a smaller number

    return triplets
