def can_form_palindrome(s):
    from collections import Counter

    # Count the frequency of each character in the string
    char_count = Counter(s)

    # Check the number of characters with odd counts
    odd_count = 0
    for count in char_count.values():
        if count % 2 != 0:
            odd_count += 1

    # For a string to be rearranged into a palindrome:
    # At most one character can have an odd count
    if odd_count > 1:
        return ""

    # If at most one character has an odd count, we can form a palindrome
    # Start forming the palindrome
    palindrome = ""
    for char, count in char_count.items():
        if count % 2 == 0:
            palindrome += char * (count // 2)
        else:
            palindrome += char * ((count - 1) // 2)

    # The palindrome can be formed by concatenating the string with its reverse
    # If there is one character with an odd count, place it in the middle
    if odd_count == 1:
        for char, count in char_count.items():
            if count % 2 != 0:
                palindrome += char

    return palindrome + palindrome[::-1]
```

