def find_divisors(n: int) -> list:
    divisors = [1]  # 1 is a divisor of all positive integers
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            divisors.append(i)
            if i != n // i:
                divisors.append(n // i)
    return divisors

def is_perfect_number(n: int) -> bool:
    if n < 1:
        return False
    return sum(find_divisors(n)) == n
