def longest_increasing_subsequence(arr):
    if not arr:
        return 0  # If the array is empty, the length of the longest increasing subsequence is 0

    # Initialize the list to store the length of the longest increasing subsequence ending at each index
    lis = [1] * len(arr)

    # Compute the longest increasing subsequence for each element in the array
    for i in range(1, len(arr)):
        for j in range(0, i):
            if arr[i] > arr[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    # The length of the longest increasing subsequence will be the maximum value in the lis list
    return max(lis)
