def reverse_palindromes(lst):
    def is_palindrome(s):
        # Convert the string to lowercase to make the function case insensitive
        s = s.lower()
        # Check if the string reads the same backward as forward
        for i in range(len(s) // 2):
            if s[i] != s[len(s) - 1 - i]:
                return False
        return True

    result = []
    for item in lst:
        if is_palindrome(item):
            # Reverse the string if it is a palindrome
            reversed_item = ""
            for char in item:
                reversed_item = char + reversed_item
            result.append(reversed_item)
        else:
            # Keep the string unchanged if it is not a palindrome
            result.append(item)

    return result
```

