from typing import List
from collections import defaultdict

class ActivityTracker:
    def __init__(self):
        self.activities = []

    def log_activity(self, timestamp: int, activity: str) -> None:
        self.activities.append((timestamp, activity))

    def get_recent_activities(self, n: int) -> List[str]:
        # Retrieve the most recent n activities in reverse chronological order
        return [activity for _, activity in self.activities[-n:][::-1]]

    def get_most_frequent_activities(self, start_time: int, end_time: int) -> List[str]:
        # Dictionary to store the frequency of activities within the specified timeframe
        activity_count = defaultdict(int)

        for timestamp, activity in self.activities:
            if start_time <= timestamp <= end_time:
                activity_count[activity] += 1

        # Sort activities first by frequency (descending) and then lexicographically (ascending)
        sorted_activities = sorted(activity_count.items(), key=lambda x: (-x[1], x[0]))

        # Extract the activities from the sorted list
        return [activity for activity, _ in sorted_activities]
```

