from typing import Optional

class FileSystemSimulator:
    def __init__(self) -> None:
        self.filesystem = {}

    def create(self, id: int, size: int, parent_id: Optional[int] = None, is_file: bool = True) -> None:
        if is_file:
            self.filesystem[id] = {'size': size, 'parent_id': parent_id, 'is_file': True}
        else:
            self.filesystem[id] = {'size': 0, 'parent_id': parent_id, 'is_file': False}

    def delete(self, id: int) -> None:
        if id in self.filesystem:
            if not self.filesystem[id]['is_file']:
                # If it's a directory, delete all its contents
                for key in list(self.filesystem.keys()):
                    if self.filesystem[key]['parent_id'] == id:
                        self.delete(key)
            del self.filesystem[id]

    def get_size(self, id: int) -> int:
        if id in self.filesystem:
            if self.filesystem[id]['is_file']:
                return self.filesystem[id]['size']
            else:
                # If it's a directory, sum the sizes of all files and subdirectories within it
                total_size = self.filesystem[id]['size']
                for key in self.filesystem.keys():
                    if self.filesystem[key]['parent_id'] == id:
                        total_size += self.get_size(key)
                return total_size
        return 0
