from typing import Optional

class FileSystemSimulator:
    def __init__(self) -> None:
        self.filesystem = {}

    def create(self, id: int, size: int, parent_id: Optional[int] = None, is_file: bool = True) -> None:
        if is_file:
            self.filesystem[id] = {'size': size, 'parent_id': parent_id, 'is_file': True}
        else:
            self.filesystem[id] = {'size': 0, 'parent_id': parent_id, 'is_file': False}

        if parent_id is not None:
            if parent_id in self.filesystem:
                if not self.filesystem[parent_id]['is_file']:
                    self.filesystem[parent_id]['size'] += size
                else:
                    raise ValueError("Parent must be a directory")
            else:
                raise ValueError("Parent does not exist")

    def delete(self, id: int) -> None:
        if id in self.filesystem:
            if self.filesystem[id]['is_file']:
                if self.filesystem[id]['parent_id'] is not None:
                    parent_id = self.filesystem[id]['parent_id']
