def largest_product(nums):
    if len(nums) < 3:
        return "Not enough elements"

    nums.sort()

    # The largest product can be either from the three largest numbers
    # or from the two smallest numbers (which could be negative) and the largest number
    return max(nums[-1] * nums[-2] * nums[-3], nums[0] * nums[1] * nums[-1])
