def longest_subarray_equal_even_odd(nums):
    if not nums:
        return 0

    # Dictionary to store the first occurrence of the difference between even and odd counts
    diff_map = {0: -1}
    even_count = 0
    odd_count = 0
    max_length = 0

    for i in range(len(nums)):
        if nums[i] % 2 == 0:
            even_count += 1
        else:
            odd_count += 1

        # Difference between even and odd counts
        diff = even_count - odd_count

        if diff in diff_map:
            # If the difference is already in the map, calculate the length of the subarray
            current_length = i - diff_map[diff]
            if current_length > max_length:
                max_length = current_length
        else:
            # Store the first occurrence of this difference
            diff_map[diff] = i

    return max_length
```

