def fibonacci_efficient(n: int) -> int:
    if n <= 1:
        return n

    # Helper function to multiply two matrices
    def multiply(mat1, mat2, result):
        for i in range(3):
            for j in range(3):
                result[i][j] = 0
                for k in range(3):
                    result[i][j] += mat1[i][k] * mat2[k][j]

    # Function to raise a matrix to the power of n using exponentiation by squaring
    def power(mat, n):
        if n == 0 or n == 1:
            return mat

        temp = [[0, 0, 0], [0, 0, 0], [0, 0, 0]]
        power(mat, n // 2)

        multiply(mat, mat, temp)

        if n % 2 != 0:
            multiply(mat, temp, mat)

        return mat

    # Base matrix for Fibonacci calculation
    F = [[1, 1, 0], [1, 0, 0], [0, 1, 0]]

    # If n is 0, the result should be 0
    if n == 0:
        return 0

    # Raise the base matrix to the power of (n-1)
    result = power(F, n - 1)

    # The top left element of the resulting matrix will be the nth Fibonacci number
    return result[0][0]
