def fibonacci_efficient(n: int) -> int:
    if n <= 1:
        return n

    def multiply(mat1, mat2, res):
        for i in range(3):
            for j in range(3):
                res[i][j] = 0
                for k in range(3):
                    res[i][j] += mat1[i][k] * mat2[k][j]

    def matrix_power(mat, n):
        if n == 0 or n == 1:
            return

        temp = [[1, 1], [1, 0]]

        while n > 0:
            if n % 2 == 1:
                multiply(mat, temp, temp)

            multiply(mat, mat, mat)
            n = n // 2

    def fibonacci_matrix(n):
        F = [[1, 1], [1, 0]]
        if n == 0:
            return 0

        matrix_power(F, n - 1)

        return F[0][0]

    return fibonacci_matrix(n)
