def validate_isbn(isbn: str) -> bool:
    # Remove hyphens from the ISBN
    isbn = isbn.replace('-', '')

    # Check if the length is either 10 or 13
    if len(isbn) != 10 and len(isbn) != 13:
        return False

    # Validate ISBN-10
    if len(isbn) == 10:
        total = 0
        for i in range(9):
            if not isbn[i].isdigit():
                return False
            total += (10 - i) * int(isbn[i])

        # Check the last character
        if isbn[9] == 'X':
            total += 1 * 10
        elif isbn[9].isdigit():
            total += 1 * int(isbn[9])
        else:
            return False

        return total % 11 == 0

    # Validate ISBN-13
    if len(isbn) == 13:
        total = 0
        for i in range(13):
            if not isbn[i].isdigit():
                return False
            if i % 2 == 0:
                total += int(isbn[i]) * 1
            else:
                total += int(isbn[i]) * 3

        return total % 10 == 0

    return False
