def is_valid_rotation(matrix):
    if not matrix or not matrix[0]:
        return False

    n = len(matrix)

    def rotate_90(mat):
        for i in range(n):
            for j in range(i, n):
                mat[i][j], mat[j][i] = mat[j][i], mat[i][j]

        for i in range(n):
            mat[i].reverse()

    def rotate_180(mat):
        for i in range(n):
            mat[i].reverse()

        for i in range(n):
            for j in range(i, n):
                mat[i][j], mat[j][i] = mat[j][i], mat[i][j]

    def rotate_270(mat):
        for i in range(n):
            for j in range(i, n):
                mat[i][j], mat[j][i] = mat[j][i], mat[i][j]

        for i in range(n):
            mat[i].reverse()

        mat.reverse()

    original_matrix = [row[:] for row in matrix]

    if matrix == rotate_90(original_matrix) or \
       matrix == rotate_180(original_matrix) or \
       matrix == rotate_270(original_matrix):
        return True

    return False
