def is_valid_roman_numeral(numeral: str) -> bool:
    if not numeral:
        return False

    roman_map = {
        'I': 1,
        'V': 5,
        'X': 10,
        'L': 50,
        'C': 100,
        'D': 500,
        'M': 1000
    }

    if any(char not in roman_map for char in numeral):
        return False

    prev_value = 0
    count = 0

    for char in reversed(numeral):
        current_value = roman_map[char]

        if current_value < prev_value:
            if current_value == prev_value // 5 or current_value == prev_value // 10:
                count += 1
                if count > 1:
                    return False
            else:
                return False
        else:
            count = 1

        if current_value > prev_value:
            prev_value = current_value
        else:
            if current_value == prev_value:
                if count >= 3:
                    return False
                count += 1
            else:
                prev_value = current_value

    return True
```

