def is_valid_roman_numeral(numeral: str) -> bool:
    # Dictionary to map Roman numeral characters to their integer values
    roman_map = {
        'I': 1,
        'V': 5,
        'X': 10,
        'L': 50,
        'C': 100,
        'D': 500,
        'M': 1000
    }

    # Check if the input string contains only valid Roman numeral characters
    for char in numeral:
        if char not in roman_map:
            return False

    # Initialize the previous value and the total value
    prev_value = 0
    total_value = 0

    # Iterate over the numeral string from right to left
    for char in reversed(numeral):
        current_value = roman_map[char]

        # If the current value is greater than or equal to the previous value, add it to the total
        if current_value >= prev_value:
            total_value += current_value
        else:
            # If the current value is less than the previous value, subtract it from the total
            total_value -= current_value

        # Update the previous value
        prev_value = current_value

    # Check for consecutive repeated characters
    for i in range(len(numeral) - 2):
        if numeral[i] == numeral[i + 1] == numeral[i + 2]:
            return False

    # Check for non-repeatable characters appearing more than once
    if 'V' in numeral and numeral.count('V') > 1:
        return False
    if 'L' in numeral and numeral.count('L') > 1:
        return False
    if 'D' in numeral and numeral.count('D') > 1:
        return False

    return True
