            prev_value = current_value
            count = 1
        elif current_value == prev_value:
            if current_value == roman_values['I'] and count >= 3:
                return False
            if current_value == roman_values['X'] and count >= 2:
                return False
            if current_value == roman_values['C'] and count >= 2:
                return False
            count += 1
        else:
            if count > 1:
                return False
            prev_value = current_value
            count = 1

    return True
