def max_tips(orders: list, tips: list, serve_time: list) -> int:
    if not orders or not tips or not serve_time:
        raise ValueError("All input lists must not be empty")

    if len(orders) != len(tips) or len(orders) != len(serve_time):
        raise ValueError("All input lists must have the same length")

    if any(tip < 0 for tip in tips):
        raise ValueError("All tips must be non-negative")

    # Create a list of tuples (end_time, order_index)
    schedule = [(serve_time[i][1], i) for i in range(len(orders))]
    schedule.sort()  # Sort based on the end time of the serve time

    # Initialize the dp array where dp[i] represents the maximum tips earned up to the i-th order
    dp = [0] * len(orders)

    for i in range(len(orders)):
        # The maximum tips earned by serving the current order is at least the tip of the current order
        dp[i] = tips[schedule[i][1]]

        # Check for the previous orders that can be served before the current order starts
        for j in range(i - 1, -1, -1):
            if schedule[j][1] < schedule[i][1]:
                dp[i] = max(dp[i], dp[j] + tips[schedule[i][1]])
                break

    # The maximum tips earned will be the maximum value in the dp array
    return max(dp)
```

