            raise ValueError("Tip amounts must be non-negative")

    for start, end in serve_time:
        if start < 0 or end < 0 or start > 24 or end > 24 or start > end:
            raise ValueError("Invalid serve times")

    # Create a list of tuples (end_time, tip) and sort it by end_time
    schedule = [(end, tip) for end, tip in zip([t[1] for t in serve_time], tips)]
    schedule.sort()

    # Initialize the maximum tips variable
    max_tips_earned = 0

    # Iterate through the sorted schedule and calculate the maximum tips
    for _, tip in schedule:
        max_tips_earned += tip

    return max_tips_earned
