def max_tips(orders: list, tips: list, serve_time: list) -> int:
    if not orders or not tips or not serve_time:
        raise ValueError("All input lists must be non-empty")

    if len(orders) != len(tips) or len(orders) != len(serve_time):
        raise ValueError("All input lists must have the same length")

    for tip in tips:
        if tip < 0:
            raise ValueError("All tips must be non-negative")

    for start, end in serve_time:
        if start < 0 or end < 0 or start > 24 or end > 24:
            raise ValueError("Serve times must be in 24-hour format and non-negative")

    # Combine orders, tips, and serve_time into a single list of tuples
    combined = list(zip(orders, tips, serve_time))

    # Sort the combined list based on the end time of the serve time
    combined.sort(key=lambda x: x[2][1])

    # Initialize the maximum tips and the end time of the last served order
    max_tips = 0
    last_served_end_time = 0

    # Iterate through the sorted list and calculate the maximum tips
    for order, tip, (start, end) in combined:
        if start >= last_served_end_time:
            max_tips += tip
            last_served_end_time = end

    return max_tips
