from typing import List

def next_smaller_permutation(nums: List[int]) -> List[int]:
    if not nums or len(nums) == 1:
        return sorted(nums, reverse=True)

    # Find the first index from the end where the current element is greater than the next element
    i = len(nums) - 2
    while i >= 0 and nums[i] <= nums[i + 1]:
        i -= 1

    # If no such index is found, the list is in ascending order, so return the list sorted in descending order
    if i == -1:
        return sorted(nums, reverse=True)

    # Find the largest index j greater than i such that nums[i] > nums[j]
    j = len(nums) - 1
    while nums[j] >= nums[i]:
        j -= 1

    # Swap the values at index i and index j
    nums[i], nums[j] = nums[j], nums[i]

    # Reverse the sublist from index i+1 to the end
    nums = nums[:i + 1] + nums[i + 1:][::-1]

    return nums
