from typing import List

def longest_subarray(arr: List[int], k: int) -> int:
    if not arr:
        return 0

    arr.sort()
    left = 0
    longest = 0

    for right in range(len(arr)):
        if arr[right] - arr[left] <= k:
            longest = max(longest, right - left + 1)
        else:
            left += 1

    return longest
```

