def min_add_to_make_valid(s):
    stack = []
    insertions = 0
    deletions = 0

    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if stack:
                stack.pop()
            else:
                deletions += 1

    insertions = len(stack)  # Each unmatched '(' requires an insertion

    return insertions + deletions
```

