def longest_increasing_subsequence(arr):
    if not arr:
        return 0, []

    n = len(arr)
    lis = [1] * n
    prev_index = [-1] * n

    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1
                prev_index[i] = j

    max_index = 0
    for i in range(1, n):
        if lis[i] > lis[max_index]:
            max_index = i

    lis_sequence = []
    while max_index != -1:
        lis_sequence.append(arr[max_index])
        max_index = prev_index[max_index]

    lis_sequence.reverse()

    return lis[max_index], lis_sequence
```

