from typing import List, Tuple

def flag_fraudulent_transactions(
    transactions: List[Tuple[str, int]],
    window: int
) -> List[str]:
    flagged_ids = []
    last_seen = {}

    for transaction_id, timestamp in transactions:
        if transaction_id in last_seen:
            if timestamp - last_seen[transaction_id] <= window:
                if transaction_id not in flagged_ids:
                    flagged_ids.append(transaction_id)
            else:
                last_seen[transaction_id] = timestamp
        else:
            last_seen[transaction_id] = timestamp

    return flagged_ids
```

