def is_magic_square(matrix):
    n = len(matrix)

    if n == 0 or any(len(row) != n for row in matrix):
        return False

    # Calculate the sum of the first row to use as a reference
    magic_sum = sum(matrix[0])

    # Check the sums of the rows
    for row in matrix:
        if sum(row) != magic_sum:
            return False

    # Check the sums of the columns
    for col in range(n):
        if sum(matrix[row][col] for row in range(n)) != magic_sum:
            return False

    # Check the sum of the main diagonal
    if sum(matrix[i][i] for i in range(n)) != magic_sum:
        return False

    # Check the sum of the secondary diagonal
    if sum(matrix[i][n-1-i] for i in range(n)) != magic_sum:
        return False

    return True
```

