from typing import List, Dict, Any, Optional
import re

def advanced_string_manipulation_and_analysis(s: str, actions: List[Dict[str, Any]]) -> List[str]:
    results = []

    for action in actions:
        action_type = action.get("type")
        if not action_type:
            raise ValueError("Action type is required")

        if action_type == "substring_count":
            value = action.get("value")
            if not value:
                raise ValueError("Value for substring_count is required")

            count = s.count(value)
            results.append(f"substring_count: {count}")

        elif action_type == "substring_replace":
            from_substring = action.get("from")
            to_substring = action.get("to")
            if not from_substring or not to_substring:
                raise ValueError("From and to substrings are required for substring_replace")

            if action.get("if_contains"):
                if action["if_contains"] in s:
                    s = s.replace(from_substring, to_substring)

            else:
                s = s.replace(from_substring, to_substring)

        elif action_type == "cipher_shift":
            shift = action.get("shift")
            if not shift:
                raise ValueError("Shift value is required for cipher_shift")

            shifted_string = ""
            for char in s:
                if char.isalpha():
                    ascii_offset = 65 if char.isupper() else 97
                    shifted_char = chr((ord(char) - ascii_offset + shift) % 26 + ascii_offset)
                    shifted_string += shifted_char
                else:
                    shifted_string += char

            s = shifted_string
            results.append(f"cipher_shift: {s}")

        elif action_type == "find_anagrams":
            word = action.get("word")
            if not word:
                raise ValueError("Word is required for find_anagrams")

            anagram_positions = [i for i in range(len(s)) if s[i:].startswith(word) and s[i:].count(word) > 1]
            results.append(f"find_anagrams: {anagram_positions}")

        elif action_type == "word_frequency":
            words = s.split()
            word_count = {}
            for word in words:
                if word in word_count:
                    word_count[word] += 1
                else:
                    word_count[word] = 1

            results.append(f"word_frequency: {word_count}")

        elif action_type == "pattern_match":
            pattern = action.get("pattern")
            if not pattern:
                raise ValueError("Pattern is required for pattern_match")

            matches = [match.start() for match in re.finditer(pattern, s)]
            results.append(f"pattern_match: {matches}")

        else:
            raise ValueError(f"Invalid action type: {action_type}")

    return results
