    nums.sort()  # Sort the array to make it easier to find pairs and avoid duplicates
    pairs = []
    left, right = 0, len(nums) - 1

    while left < right:
        current_sum = nums[left] + nums[right]

        if current_sum == target:
            # If the pair is not already in the list, add it
            if (nums[left], nums[right]) not in pairs:
                pairs.append((nums[left], nums[right]))

            # Move both pointers to find other possible pairs
            left += 1
            right -= 1

            # Skip duplicate values for the left pointer
            while left < right and nums[left] == nums[left - 1]:
                left += 1

            # Skip duplicate values for the right pointer
            while left < right and nums[right] == nums[right + 1]:
                right -= 1

        elif current_sum < target:
            left += 1  # Move the left pointer to increase the sum
        else:
            right -= 1  # Move the right pointer to decrease the sum

    return pairs
```

